{
  "name": "实验数据加载与绘图工具",
  "name_en": "Experimental Data Loader and Plotter",
  "manufacturer": "",
  "description": "用于从 HDF5 实验数据文件中读取多维测量数据、进行筛选、平均和维度整理，并将结果显示到对应视图中的实验数据后处理软件组件。常用于实验结果浏览、快速检查和基础可视化。",
  "description_en": "A post-processing software component that loads multidimensional measurement data from HDF5 experimental data files, applies filtering, averaging, and dimension handling, and displays the results in appropriate viewers. It is used for browsing, quick inspection, and basic visualization of experimental results.",
  "tag_hints": [
    "HDF5 data loading",
    "scientific data visualization",
    "multidimensional data",
    "post-processing",
    "data averaging",
    "viewer management"
  ],
  "actions": [
    {
      "action_name": "auto-viewers",
      "description": "获取当前查看器列表。",
      "description_en": "Get the current list of viewers."
    },
    {
      "action_name": "auto-connect_double_clicked",
      "description": "连接双击事件回调。",
      "description_en": "Connect a callback to the double-click event."
    },
    {
      "action_name": "auto-clear_viewers",
      "description": "清空所有查看器中的显示内容。",
      "description_en": "Clear the displayed content in all viewers."
    },
    {
      "action_name": "auto-h5saver",
      "description": "获取或设置当前 HDF5 数据源。",
      "description_en": "Get or set the current HDF5 data source."
    },
    {
      "action_name": "auto-data",
      "description": "获取当前已加载的数据。",
      "description_en": "Get the currently loaded data."
    },
    {
      "action_name": "auto-load_data",
      "description": "从当前 HDF5 节点加载数据，并进行筛选或基础处理。",
      "description_en": "Load data from the current HDF5 node and apply filtering or basic processing."
    },
    {
      "action_name": "auto-average_axis",
      "description": "沿指定轴对数据进行平均。",
      "description_en": "Average the data along a selected axis."
    },
    {
      "action_name": "auto-remove_navigation_axes",
      "description": "移除导航轴并将其转换为信号显示形式。",
      "description_en": "Remove navigation axes and convert them into signal-display form."
    },
    {
      "action_name": "auto-group_0D_data",
      "description": "将多个 0 维标量数据分组为单个数据集。",
      "description_en": "Group multiple 0D scalar data items into a single dataset."
    },
    {
      "action_name": "auto-load_plot_data",
      "description": "从当前 HDF5 数据源加载并绘制全部数据。",
      "description_en": "Load and plot all data from the current HDF5 data source."
    },
    {
      "action_name": "auto-show_data",
      "description": "将数据发送到对应查看器并显示。",
      "description_en": "Send data to the appropriate viewers for display."
    },
    {
      "action_name": "auto-prepare_viewers",
      "description": "为指定数据类型准备查看器。",
      "description_en": "Prepare viewers for the specified data types."
    },
    {
      "action_name": "auto-set_data_to_viewers",
      "description": "根据数据维度将数据分配到合适的查看器。",
      "description_en": "Route data to suitable viewers according to data dimensionality."
    }
  ]
}

